glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
#if USE_TEXTURE
  uniform sampler2D cc_spriteTexture;
#endif
layout(std140) uniform Constants {
  float u_time;
  float u_intensity;
  float u_rimWidth;
  float u_sweepSpeed;
  float u_fireAmt;
  float u_shimmer;
};
float hash (vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float vnoise (vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i), b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0)), d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm (vec2 p) {
  float v = 0.0, amp = 0.5;
  for (int i = 0; i < 3; i++) { v += amp * vnoise(p); p *= 2.0; amp *= 0.5; }
  return v;
}
vec3 fireRamp (float t) {
  vec3 c = vec3(0.0);
  c = mix(c, vec3(0.6, 0.05, 0.0), smoothstep(0.0, 0.3, t));
  c = mix(c, vec3(1.0, 0.35, 0.0), smoothstep(0.3, 0.55, t));
  c = mix(c, vec3(1.0, 0.8, 0.2),  smoothstep(0.55, 0.8, t));
  c = mix(c, vec3(1.0, 1.0, 0.85), smoothstep(0.8, 1.0, t));
  return c;
}
vec3 hue (float h) {
  return clamp(abs(fract(h + vec3(0.0, 0.6667, 0.3333)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
}
vec4 frag () {
  float a = 1.0;
  #if USE_TEXTURE
    a = CCSampleWithAlphaSeparated(cc_spriteTexture, uv0).a;
  #endif
  float pulse = 0.55 + 0.45 * sin(u_time * 5.0);
  float band = 0.5 + 0.5 * sin((uv0.x - uv0.y) * 7.0 - u_time * 2.2);
  band = pow(band, 2.5);
  vec3 irid = hue(fract((uv0.x + uv0.y) * 0.6 + u_time * 0.25));
  vec3 shimmerCol = mix(vec3(1.0), irid, 0.8);
  float shimmer = band * a * u_shimmer * (0.6 + 0.4 * pulse);
  vec2 gp = uv0 - vec2(0.5 + 0.26 * sin(u_time * 0.7), 0.55 + 0.22 * cos(u_time * 0.9));
  float cross = max(exp(-abs(gp.x) * 55.0), exp(-abs(gp.y) * 55.0));
  float glint = cross * exp(-dot(gp, gp) * 22.0) * (0.35 + 0.65 * pow(pulse, 3.0)) * a;
  float lo = 0.5 - u_rimWidth * 10.0;
  float rim = smoothstep(lo, 0.5, a) * (1.0 - smoothstep(0.5, 0.97, a));
  rim = pow(clamp(rim, 0.0, 1.0), 0.6) * (0.7 + 0.55 * pulse);
  vec3 rimCol = mix(vec3(1.0, 0.55, 0.15), vec3(1.0, 0.95, 0.78), 0.5 + 0.5 * sin(u_time * 3.0));
  float ft = u_time * 1.6;
  vec2 np = vec2(uv0.x * 3.0 + sin(uv0.y * 6.0 + ft) * 0.16, uv0.y * 3.2 - ft * 1.25);
  float flame = pow(fbm(np) * pow(smoothstep(0.72, 0.0, uv0.y), 1.5), 1.5) * a;
  vec3 fireCol = fireRamp(clamp(flame, 0.0, 1.0));
  float fireA = clamp(flame, 0.0, 1.0) * 0.5 * u_fireAmt;
  float diag = (uv0.x + (1.0 - uv0.y)) * 0.5;
  float sweep = (1.0 - smoothstep(0.0, 0.13, abs(diag - fract(u_time * u_sweepSpeed)))) * a;
  vec3 rgb = fireCol * fireA
           + rimCol * rim
           + shimmerCol * shimmer * 0.85
           + vec3(1.0) * glint * 1.25
           + vec3(1.0, 0.98, 0.92) * sweep * 0.7;
  float outA = clamp(fireA + rim + shimmer * 0.78 + glint * 1.05 + sweep * 0.7, 0.0, 1.0)
             * u_intensity * color.a;
  vec4 col = vec4(rgb, outA);
  ALPHA_TEST(col);
  return col;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

